#ifndef CSM_REPORT_H
#define CSM_REPORT_H

#include <stddef.h>

#include "move.h"

/*
 * What a run of the core says, as lines of text: the CLI prints them,
 * the TUI shows them as the preview of a change.
 */
struct report_line {
	enum note_level level;
	int indent;		/* 0: a heading, 1: under it, 2: the plan */
	char *text;
};

struct report {
	struct report_line *lines;
	size_t count, cap;
};

char *report_path(const struct move_ctx *ctx, const char *path);
void report_add(struct report *r, enum note_level level, int indent,
    char *text);
void report_notes(struct report *r, const struct move_ctx *ctx, int quiet);
void report_plan(struct report *r, const struct move_ctx *ctx);
size_t report_count(const struct report *r, enum note_level level);
void report_free(struct report *r);

#endif
